import{_ as e,V as o,W as p,a0 as a}from"./framework-9a29aaa0.js";const r={},t=a('<ul><li><a href="#cs-6824-%E7%AC%AC8%E8%AE%B2-zookeeper">cs-6.824 第8讲 zookeeper</a></li></ul><h1 id="cs-6-824-第8讲-zookeeper" tabindex="-1"><a class="header-anchor" href="#cs-6-824-第8讲-zookeeper" aria-hidden="true">#</a> cs-6.824 第8讲 zookeeper</h1><p>今天的论文是关于线性一致性的，之所以要研读zookeeper的论文，部分原因是它是一个成功的现实世界系统，这是一个开源服务，很多人在使用它，已经被应用于众多实际软件中，因此它具有一定的实际效果和成功之处。</p><p>raft是一个库而不是一个服务，因此需要代码层级的集成，因此人们希望有一个服务可以做到像raft那样的功能，帮助人们快速的构建分布式系统。</p><p>另外一点，zookeeper本身也需要具有容错性，可能是三台、五台、七台等等。</p><p>它运行将读操作分散到任意副本上进行，因此读取的内容可能不是最新的。另一方面，zookeeper确保每个副本按照顺序逐一处理写入流，所有副本均按照相同的顺序执行写操作。所有由单个客户端生成的读写操作，系统也会按照顺序处理。</p><p>zookeeper可以解决那些问题？</p><ul><li>VMWare VT test and set service</li><li>发布配置信息供其他服务器使用。</li></ul><p>Zookeeper的API像是一个文件系统，所以它拥有一个目录结构。</p><p>CREATE(path, data, flag)</p><p>DELETE(path, version)</p><p>EXISTS(path, watch);</p><p>example-count</p>',13),s=[t];function c(l,n){return o(),p("div",null,s)}const h=e(r,[["render",c],["__file","lesson8.html.vue"]]);export{h as default};
